import {createSimulation,TASKS,PLACES} from './sim.js';
import {drawWorld,pawnIcon} from './art.js';
const $=id=>document.getElementById(id);
const initialSeed=Number(new URLSearchParams(location.search).get('seed'))||8291;
const sim=createSimulation(initialSeed);let selected='you',momentsOnly=false,lastRender=0,lastSerial=-1,endingShown=false,hover=null,hitboxes=[];const offerChoices={};
const momentTypes=new Set(['join','promise','kept','broken','conflict','aid','death','departure','ending','shelter']);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
function feedback(result){$('feedback').textContent=result.message;$('feedback').classList.toggle('error',!result.ok);}
function act(command){const r=sim.command(command);feedback(r);render(true);return r;}
window.Return=Object.freeze({observe:()=>sim.observe(),command:cmd=>act(cmd),help:()=>({commands:['intent','request','invite','promise','donate','policy','pause','speed','step','restart'],tasks:TASKS,example:{type:'request',actorId:'mira',task:'forage',offer:'meal'}})});
function select(id){selected=id;render(true);}
function roster(view){$('people').innerHTML=view.people.map(p=>`<button class="person-card ${selected===p.id?'selected':''} ${!p.joined?'visitor':''} ${!p.alive||p.left?'gone':''}" data-person="${p.id}" aria-pressed="${selected===p.id}">${pawnIcon(p)}<span class="person-info"><strong>${safe(p.name)}${p.id==='you'?' <small>↰</small>':''}</strong><span>${!p.alive?'Died':p.left?'Left the camp':!p.joined?'Stranger · '+p.species:(p.intent?TASKS[p.intent.task]||'Giving blood':TASKS[p.job?.task]||cap(p.role))}</span></span><span class="status-dot ${p.health<45||p.hunger>85?'bad':p.fatigue>72||!p.joined?'warn':''}"></span></button>`).join('');for(const btn of $('people').querySelectorAll('[data-person]'))btn.onclick=()=>select(btn.dataset.person);$('cast-count').textContent=view.people.filter(p=>p.alive&&!p.left).length+' nearby';}
function need(label,value,good=false){const bad=good?value<40:value>80,warn=good?value<70:value>60;return `<div class="need ${bad?'bad':warn?'warn':''}"><div class="need-label"><span>${label}</span><strong>${Math.round(value)} / 100</strong></div><div class="meter"><i style="width:${value}%"></i></div></div>`;}
function inspector(view){const p=view.people.find(p=>p.id===selected)||view.people[0];if(!p)return;const available=p.alive&&!p.left;const offers=p.species==='vampire'?'<option value="rest">Promise protected rest</option>':'<option value="meal">Promise a meal</option><option value="rest">Promise time to rest</option>';
 const own=p.id==='you';const promises=view.promises.filter(o=>o.to===p.id).slice(-4);const vampires=view.people.filter(v=>v.joined&&v.alive&&!v.left&&v.species==='vampire');
 $('inspector').innerHTML=`<div class="person-header"><span class="eyebrow">${own?'THE RETURNED STRANGER':!available?'PART OF THIS CAMP’S HISTORY':p.joined?'COMPANION':'A POSSIBLE ALLY'}</span><div class="name-row">${pawnIcon(p,true)}<div><h2>${safe(p.name)}</h2><p>${cap(p.species)} · ${p.species==='vampire'?'Blood, shade, and a place to belong':cap(p.role)}</p></div></div><div class="trait-list">${p.traits.map((t,i)=>`<span class="trait" title="${safe(p.traitDescriptions[i])}">${t}</span>`).join('')}</div></div><div class="inspector-content">${need(p.species==='vampire'?'Blood hunger':'Hunger',p.hunger)}${need('Fatigue',p.fatigue)}${need('Health',p.health,true)}<div class="want"><span>WHAT MATTERS RIGHT NOW</span><p>${safe(p.desire)}</p></div>${p.speech?`<p class="speech">“${safe(p.speech)}”</p>`:''}${!own?`<div class="trust-line"><span>Trust in you</span><b>${safe(p.trustLabel)} · ${p.trust.you||0}</b></div>`:''}${!p.joined&&available?'<button id="invite-person" class="primary invite-button">Offer a place in the camp</button><p class="empty-note">A human asks for a meal. A vampire asks for protected rest. Both expect you to keep your word.</p>':''}${available&&p.joined?`<span class="section-label">${own?'YOUR NEXT INTENTION':'REQUEST FOR NEXT SHIFT'}</span>${!own?`<select class="offer-select" id="work-offer" aria-label="What you offer in return"><option value="">Ask without a bargain</option>${offers}</select>`:''}<div class="action-grid">${Object.entries(TASKS).map(([id,label])=>`<button data-task="${id}" class="${p.intent?.task===id?'next':''}">${label}</button>`).join('')}</div><p class="intention">${p.intent?'Next: '+safe(TASKS[p.intent.task]||'Give blood')+'. ':''}${p.job?'Now: '+safe(p.job.reason||TASKS[p.job.task]||'Resting'):'People will act when time passes.'}</p>${p.species==='vampire'?'<div class="donate-row"><button id="donate-own">Offer your blood · −13 health</button></div>':vampires.length?`<div class="donate-row"><select id="blood-target" aria-label="Blood recipient">${vampires.map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}</select><button id="donate-selected">${own?'Offer your blood':'Ask to give blood'} · −13 health</button></div>`:''}${!own?`<div class="donate-row"><button id="promise-rest">Promise rest</button>${p.species==='human'?'<button id="promise-meal">Promise a meal</button>':''}</div>`:''}`:!available?'<p class="empty-note">Their actions remain in the camp’s history.</p>':''}${promises.length?`<span class="section-label">YOUR WORD TO ${own?'YOURSELF':p.name.toUpperCase()}</span><ul class="promise-list">${promises.map(o=>`<li class="${o.status}">${o.status==='open'?'○':o.status==='kept'?'✓':'×'} ${o.type==='meal'?'A meal':'Time to rest'} · ${o.status==='open'?'due shift '+o.due:o.status}</li>`).join('')}</ul>`:''}${p.memories.length?`<span class="section-label">WHAT ${own?'YOU REMEMBER':p.name.toUpperCase()+' REMEMBERS'}</span><ul class="memory-list">${p.memories.slice(0,4).map(m=>`<li>${safe(m.text)}</li>`).join('')}</ul>`:''}</div>`;
 if($('work-offer')){$('work-offer').value=offerChoices[p.id]||'';$('work-offer').onchange=e=>{offerChoices[p.id]=e.target.value;};}
 $('invite-person')?.addEventListener('click',()=>act({type:'invite',actorId:p.id}));
 for(const b of $('inspector').querySelectorAll('[data-task]'))b.onclick=()=>{const offer=$('work-offer')?.value||undefined;act({type:own?'intent':'request',actorId:p.id,task:b.dataset.task,offer});};
 $('donate-own')?.addEventListener('click',()=>act({type:'donate',actorId:'you',target:p.id}));
 $('donate-selected')?.addEventListener('click',()=>act({type:'donate',actorId:p.id,target:$('blood-target').value}));
 $('promise-rest')?.addEventListener('click',()=>act({type:'promise',actorId:p.id,offer:'rest'}));
 $('promise-meal')?.addEventListener('click',()=>act({type:'promise',actorId:p.id,offer:'meal'}));
}
function history(view){if(lastSerial===sim.state.serial&&$('events').dataset.filter===String(momentsOnly))return;lastSerial=sim.state.serial;$('events').dataset.filter=String(momentsOnly);const items=view.events.filter(e=>!momentsOnly||momentTypes.has(e.type)).slice(-55).reverse();$('events').innerHTML=items.map(e=>`<div class="event ${e.type} ${momentTypes.has(e.type)?'moment':''}"><span class="event-time">${e.shift?'S'+e.shift:'DAWN'}</span><div class="event-text">${['broken','kept','aid','conflict','join','departure'].includes(e.type)?`<span class="event-chip">${e.type==='aid'?'care':e.type}</span>`:''}${safe(e.text)}</div></div>`).join('');}
function render(force=false){const view=sim.observe();$('food').textContent=view.resources.food;$('wood').textContent=view.resources.wood;$('roof').textContent=view.resources.shelter+'/3';const day=Math.floor((Math.max(1,view.shift)-1)/6)+1;const times=['Morning','Late morning','Afternoon','Dusk','Night','Before dawn'];$('time-label').textContent='Day '+day+' · '+times[(Math.max(1,view.shift)-1)%6];$('weather-label').textContent=view.weather;$('map-status').textContent=view.ended?'This camp’s story is complete':view.paused?'Time is paused · room to think':view.night?'Night shift · the vampires can work outside':'Day shift · sunlight keeps the vampires under cover';$('pause-label').textContent=view.paused?'Let time pass':'Pause time';$('pause-symbol').textContent=view.paused?'▶':'Ⅱ';$('shift-count').textContent='Shift '+view.shift+' / 12';$('ration-policy').value=view.policy;document.querySelectorAll('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===view.speed));const friends=view.people.filter(p=>p.joined&&p.alive&&!p.left&&p.id!=='you').length;$('goal-progress').textContent=friends+' / 3 companions';$('goal-text').textContent=view.ended?(view.result.won?'This camp has a future.':'Every choice left a trace.'):'Stay alive. Repair the roof. End with 3 meals.';if(force||performance.now()-lastRender>550){roster(view);inspector(view);lastRender=performance.now();}history(view);if(view.ended&&!endingShown)showEnding(view);}
function showEnding(view){endingShown=true;const r=view.result;$('ending-title').textContent=!r.alive?'A life cut short':r.won?'A place to return to':'Still a fragile beginning';$('ending-copy').textContent=!r.alive?'You did not survive these two days. The people and promises you left behind explain how the camp reached this point.':r.won?'The roof holds. There is food for tomorrow. At least three people have chosen to share this place with you.':'You survived, but the camp is short of shelter, supplies, or people willing to stay. Its history is still yours to understand.';$('ending-stats').innerHTML=`<div><b>${r.friends}</b><span>companions remain</span></div><div><b>${r.roof}/3</b><span>shelter repaired</span></div><div><b>${r.food}</b><span>meals for tomorrow</span></div>`;const events=view.events.filter(e=>['kept','broken','aid','conflict','departure','death'].includes(e.type)).slice(-4);$('ending-moments').innerHTML=events.length?events.map(e=>'<p>'+safe(e.text)+'</p>').join(''):'<p>The quiet shifts count too. Whom would you treat differently next time?</p>';$('ending').showModal();}
const canvas=$('world'),ctx=canvas.getContext('2d');
function draw(){hitboxes=drawWorld(canvas,ctx,sim,selected);}
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect();const hit=hitboxes.findLast(p=>Math.abs(p.x-(e.clientX-r.left))<p.r&&Math.abs(p.y-(e.clientY-r.top))<p.r);if(hit)select(hit.id);});
$('pause').onclick=()=>act({type:'pause'});$('step').onclick=()=>act({type:'step'});for(const b of document.querySelectorAll('[data-speed]'))b.onclick=()=>act({type:'speed',value:Number(b.dataset.speed)});$('ration-policy').onchange=e=>act({type:'policy',value:e.target.value});
$('begin').onclick=()=>{$('welcome').close();act({type:'pause',value:false});};$('begin-paused').onclick=()=>{$('welcome').close();act({type:'pause',value:true});};$('help').onclick=()=>{sim.command({type:'pause',value:true});render(true);$('welcome').showModal();};
function openRestart(){$('ending').close();sim.command({type:'pause',value:true});$('seed-input').value=Math.floor(Math.random()*999999)+1;$('restart').showModal();render(true);}
$('new-camp').onclick=openRestart;$('ending-restart').onclick=openRestart;$('cancel-restart').onclick=()=>$('restart').close();$('confirm-restart').onclick=()=>{sim.command({type:'restart',seed:Number($('seed-input').value)});selected='you';endingShown=false;lastSerial=-1;$('restart').close();render(true);feedback({ok:true,message:'A new beginning. Choose an intention and let time pass.'});};$('ending-close').onclick=()=>$('ending').close();
$('filter-moments').onclick=()=>{momentsOnly=!momentsOnly;$('filter-moments').setAttribute('aria-pressed',String(momentsOnly));$('filter-moments').textContent=momentsOnly?'Show all events':'Only turning points';render();};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(sim.observe(),null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='return-camp-'+sim.state.seed+'-record.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('console-toggle').onclick=()=>{$('console-panel').hidden=!$('console-panel').hidden;if(!$('console-panel').hidden)$('console-input').focus();};$('console-form').onsubmit=e=>{e.preventDefault();try{$('console-output').textContent=JSON.stringify(act(JSON.parse($('console-input').value)),null,2);}catch(err){$('console-output').textContent='Invalid JSON: '+err.message;}};$('observe').onclick=()=>{$('console-output').textContent=JSON.stringify(sim.observe(),null,2);};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();act({type:'pause'});}if(e.code==='Period'){e.preventDefault();act({type:'step'});}if(['Digit1','Digit2','Digit3'].includes(e.code))act({type:'speed',value:{Digit1:1,Digit2:3,Digit3:8}[e.code]});});
let last=performance.now();function frame(now){sim.elapse(Math.min(.1,(now-last)/1000));last=now;draw();if(now-lastRender>400)render();requestAnimationFrame(frame);}render(true);$('welcome').showModal();requestAnimationFrame(frame);
